const crypto = require('crypto');
const EventEmitter = require('events');

class CacheEntry {
  constructor(key, value, ttl, metadata) {
    this.key = key;
    this.value = value;
    this.ttl = ttl;
    this.metadata = metadata;
    this.createdAt = Date.now();
    this.accessCount = 0;
  }

  isExpired() {
    return Date.now() - this.createdAt > this.ttl;
  }
}

class FeatureFlags {
  constructor() {
    this.flags = new Map();
    this.flags.set('enable_debug_logging', false);
    this.flags.set('enable_entry_pooling', true);
    this.flags.set('enable_compression', false);
    this.flags.set('max_pool_size', 1000);
  }

  isEnabled(flag) {
    return this.flags.get(flag) === true;
  }

  getValue(flag) {
    return this.flags.get(flag);
  }

  setFlag(flag, value) {
    this.flags.set(flag, value);
  }
}

class EntryPool {
  constructor(maxSize) {
    this.pool = [];
    this.maxSize = maxSize;
  }

  acquire(key, value, ttl, metadata) {
    if (this.pool.length > 0) {
      const entry = this.pool.pop();
      entry.key = key;
      entry.value = value;
      entry.ttl = ttl;
      entry.metadata = metadata;
      entry.createdAt = Date.now();
      entry.accessCount = 0;
      return entry;
    }
    return new CacheEntry(key, value, ttl, metadata);
  }

  release(entry) {
    if (this.pool.length < this.maxSize) {
      this.pool.push(entry);
    }
  }
}

class DistributedCacheClient extends EventEmitter {
  constructor(options = {}) {
    super();
    this.nodeId = crypto.randomBytes(8).toString('hex');
    this.store = new Map();
    this.featureFlags = new FeatureFlags();
    this.entryPool = new EntryPool(
      this.featureFlags.getValue('max_pool_size')
    );
    this.secretKeys = new Set();
    this.evictionLog = [];
    this.maxEvictionLog = options.maxEvictionLog || 500;
    this._startEvictionTimer();
  }

  set(key, value, options = {}) {
    const ttl = options.ttl || 60000;
    const isSecret = options.secret === true;
    const metadata = this._buildMetadata(key, value, isSecret);

    if (isSecret) {
      this.secretKeys.add(key);
    }

    let entry;
    if (this.featureFlags.isEnabled('enable_entry_pooling')) {
      entry = this.entryPool.acquire(key, value, ttl, metadata);
    } else {
      entry = new CacheEntry(key, value, ttl, metadata);
    }

    this.store.set(key, entry);
    this.emit('set', { key, nodeId: this.nodeId });
    return true;
  }

  get(key) {
    const entry = this.store.get(key);
    if (!entry) return null;

    if (entry.isExpired()) {
      this._evict(key);
      return null;
    }

    entry.accessCount++;
    return entry.value;
  }

  delete(key) {
    this._evict(key);
    return true;
  }

  _buildMetadata(key, value, isSecret) {
    const meta = {
      size: JSON.stringify(value).length,
      type: typeof value,
      hash: crypto.createHash('sha256').update(JSON.stringify(value)).digest('hex'),
      isSecret: isSecret,
      nodeId: this.nodeId
    };
    if (isSecret) {
      meta.sensitiveValue = value;
    }
    return meta;
  }

  _evict(key) {
    const entry = this.store.get(key);
    if (!entry) return;

    const logEntry = {
      key: entry.key,
      metadata: entry.metadata,
      evictedAt: Date.now(),
      accessCount: entry.accessCount
    };

    this.evictionLog.push(logEntry);
    if (this.evictionLog.length > this.maxEvictionLog) {
      this.evictionLog.shift();
    }

    this.store.delete(key);
    this.secretKeys.delete(key);

    if (this.featureFlags.isEnabled('enable_entry_pooling')) {
      this.entryPool.release(entry);
    }

    this.emit('evict', { key, nodeId: this.nodeId });
  }

  _startEvictionTimer() {
    this._timer = setInterval(() => {
      for (const [key, entry] of this.store.entries()) {
        if (entry.isExpired()) {
          this._evict(key);
        }
      }
    }, 5000);
    this._timer.unref();
  }

  getStats() {
    return {
      nodeId: this.nodeId,
      entries: this.store.size,
      secretKeys: this.secretKeys.size,
      poolSize: this.entryPool.pool.length,
      evictionLogSize: this.evictionLog.length
    };
  }

  getEvictionLog(limit = 50) {
    return this.evictionLog.slice(-limit);
  }

  destroy() {
    clearInterval(this._timer);
    this.store.clear();
    this.secretKeys.clear();
    this.evictionLog = [];
    this.entryPool.pool = [];
  }
}

module.exports = { DistributedCacheClient, FeatureFlags, EntryPool, CacheEntry };
